INSERT INTO skill_templates (name, usage_detail, effect, tradeoff, cong_duc_cost, am_duc_cost, duration, mental_effect, mental_duration, health_effect, health_duration, spiritual_effect, spiritual_duration, ghost_level_effect, destruction_percent, category, account, oc_name, nghe, phe_duyet) VALUES
('Lập Trận', 'Dựa vào địa hình, phương vị và các vật dẫn có sẵn để nhanh chóng bố trí một trận pháp tạm thời, tạo ra phạm vi ngăn cản, làm chậm hoặc hạn chế quỷ dị trong thời gian ngắn. Hiệu quả phụ thuộc vào địa hình và cấp độ của quỷ dị. Du hồn trong 3 cmt, oán hồn 2 cmts và lệ quỷ 1 cmts', 'Tiêu hao từ 20% đến 70% thể lực để duy trì trận pháp, tuỳ theo cấp độ quỷ dị và độ khó của dị sự.  Không thể sử dụng trong 2 dị sự liên tiếp nhau', '', 46082, 0, '1 - 3', 'Mất phương hướng', 3, 'Suy nhược', 3, 'Âm khí xâm nhập', 3, '', 0, 'Đạo sĩ', 'Đề Chủy Tửu', 'Kỷ Huyền Sâm', 'Đạo sĩ', 'Đã duyệt'),
('Đoán địa thế & Khí vi', 'Dùng La bàn cổ, quan sát dòng chảy nước, hướng gió, mùi ẩm mốc và vệt ố trên tường/đất. Tìm ra nguồn cơn thực sự của "tà khí" (nguồn nước nhiễm độc, khí mỏ, nấm độc tích tụ). Giúp bản thân và đồng đội tránh được vùng không khí độc, phát hiện ra mật đạo hoặc nơi kẻ gian cất giấu đồ. Tỷ lệ sai sót là 40%', 'Không', '', 0, 0, '', 'Nhạy cảm với các giác quan, Căng thẳng', 10, 'Khỏe mạnh', 0, 'Thanh khiết', 0, '', 0, 'Trừ ma sư nhân gian', 'Án Tửu Chương', 'Trầm Trực', 'Trừ ma sư nhân gian', 'Đã duyệt'),
('Võ thuật Pháp khí', 'Tấn công trực diện bằng Kiếm gỗ đào (có lõi thép/nặng cứng) và Ấn đồng nặng trịch kết hợp đòn chân, gạt đỡ. Khống chế, tước vũ khí hoặc hạ gục đối thủ trong khoảng cách gần. Gây sát thương vật lý thực tế (choáng váng, gãy xương, rách thịt) lên kẻ gian đang giả thần giả quỷ.', 'Không', '', 0, 0, '', 'Khỏe mạnh', 0, 'Khỏe mạnh', 0, 'Thanh khiết', 0, '', 0, 'Trừ ma sư nhân gian', 'Án Tửu Chương', 'Trầm Trực', 'Trừ ma sư nhân gian', 'Đã duyệt'),
('Định Hồn Phạn', 'Dùng móng tay tẩm chu sa cắn rách đầu ngón, bấm huyết phù lên không trung kết hợp tụng xuất từng âm tiết kinh chú theo đúng tần số cổ pháp. Mỗi âm chú xướng lên đồng thời bắn ra một đạo huyết phù cắm xuống mặt đất để xác lập một Trận Nhãn.  Dựng “tường lửa lọc âm” trong phạm vi 20m, ổn định trường âm thanh bên trong, ngăn ảo thanh, tiếng gọi hồn, tiếng khóc than, gào rú và các sóng âm ô uế xâm nhập, bảo vệ thần trí và tránh mê hoặc, mất kiểm soát.', '- Nếu cưỡng ép duy trì quá 3 phút hoặc gượng ép khai trận lần 2: Kinh mạch tai bị chấn rách dẫn đến chảy máu tai, gây mất thính lực, tiếp tục nữa (lần 3) sẽ chết.', '', 0, 0, '1.0', 'Rối trí, Quá tải giác quan', 2, 'Suy giảm nặng các giác quan', 2, 'Bất tịnh, Tà khí nhập thể', 2, '', 0, 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Thục Hương Ngữ', 'Thục Hương Ngữ', 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Đã duyệt'),
('Tịch Tĩnh Giới', 'Tạo một không gian cách âm tuyệt đối phạm vi 10m, nuốt trọn mọi âm thanh phát ra từ bên trong như tiếng thở, bước chân, nhịp tim và va chạm, qua đó che giấu sự hiện diện khỏi tà vật dò tìm bằng thính giác hoặc chấn động âm khí. Tuy nhiên, không có tác dụng với quỷ dị sở hữu phương thức cảm nhận khác ngoài thính giác. Thường dùng khi cần trốn chạy, lẩn trốn hoặc vượt qua những bầy quỷ bị mù nhưng có thính giác nhạy bén. Không có tác dụng với Quỷ Tướng và Quỷ Vương', 'Không', '', 0, 0, '1.0', 'Mơ hồ, Nhạy cảm với các giác quan, Mất phương hướng', 3, 'Khó thở, Ù tai', 2, 'Thanh khiết', 3, '', 0, 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Thục Hương Ngữ', 'Thục Hương Ngữ', 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Đã duyệt'),
('Huyễn Âm Dẫn Hồn', 'Bẻ cong và giả lập âm thanh, tạo ra tiếng mõ hoặc tụng kinh tại một vị trí khác trong trận để đánh lạc hướng, dụ quỷ di chuyển về phía đó, tạo thời gian cho đồng đội chạy trốn hoặc đưa quỷ vào bẫy/phong ấn. Không thể cưỡng ép quỷ dị di chuyển theo ý muốn; hiệu quả phụ thuộc vào Quỷ Tính và Quỷ Luật của mục tiêu. Không có tác dụng với Quỷ Tướng và Quỷ Vương', '', '', 20, 0, '1.0', 'Rối trí, Quá tải giác quan, Nhạy cảm với các giác quan', 3, 'Đau đầu', 2, 'Bất tịnh, Tà khí nhập thể', 3, '', 0, 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Thục Hương Ngữ', 'Thục Hương Ngữ', 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Đã duyệt'),
('Hộ Giới Âm', 'Dựng một vòm kết giới phạm vi 10m đẩy lùi tà khí, bảo vệ người bên trong khỏi du hồn, oán hồn, lê quỷ và các đòn ám khí nguyền rủa từ xa. Quỷ dj không thể trực tiếp chạm vào người trong tâm trận, nhưng kết giới không tuyệt đối và không thể ngăn những năng lực được Quỷ Luật xác định có khả năng xuyên qua kết giới.', '', '', 10, 0, '1.0', 'Quá tải giác quan, Ảo giác', 3, 'Mất thính giác', 3, 'Oán khí quấn thân', 3, '', 0, 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Thục Hương Ngữ', 'Thục Hương Ngữ', 'Ni sư Giám viện kiêm Tri sự tại Thất Huy Cổ Am', 'Đã duyệt'),
('Cầm trận - Định Âm', '"Mỗi khi tấu đàn theo một âm luật nhất định, người sử dụng có thể thiết lập một trận pháp bằng các điểm cộng hưởng âm thanh trong phạm vi. Khi trận hoàn thành, khu vực bên trong sẽ bị ảnh hưởng bởi quy luật âm thanh được thiết lập.  Cách kích hoạt: Dùng cổ cầm tấu liên tiếp các âm theo đúng âm luật. Mỗi âm sẽ xác lập một trận điểm. Cần tối thiểu 3 trận điểm để hình thành trận, tối đa 5 trận điểm.  Hiệu quả: quét qua toàn bộ âm thanh trong bán kính 100m theo hình cầu, xác định cụ thể sinh vật/linh lực di chuyển trong bán kính. Trong thời gian kích hoạt Định Âm, người sử dụng không thể bị phát hiện. Đối với quỷ dị, chỉ có thể xác định sự tồn tại và vị trí tương đối, không tự động biết thân phận, cấp bậc, điểm yếu hay Quỷ Luật."', 'Mỗi lần hoàn thành một trận, Cầm sư phải chịu ù tai và mất thính lực tạm thời, nếu cưỡng ép duy trì trận quá thời gian cho phép, có nguy cơ chảy máu tai, mất thăng bằng hoặc tổn thương thính giác.', '', 0, 0, '3.0', 'Nhạy cảm với các giác quan, Thất thần', 2, 'Ù tai', 2, 'Linh hồn chịu áp lực lớn', 2, '', 0, 'Cầm sư', 'Tố Kiều Lê', 'Trúc Khinh Nhu', 'Cầm sư', 'Đã duyệt'),
('Cầm trận - Tĩnh Âm', '"Mỗi khi tấu đàn theo một âm luật nhất định, người sử dụng có thể thiết lập một trận pháp bằng các điểm cộng hưởng âm thanh trong phạm vi. Khi trận hoàn thành, khu vực bên trong sẽ bị ảnh hưởng bởi quy luật âm thanh được thiết lập.  Cách kích hoạt: Dùng cổ cầm tấu liên tiếp các âm theo đúng âm luật. Mỗi âm sẽ xác lập một trận điểm. Cần tối thiểu 3 trận điểm để hình thành trận, tối đa 5 trận điểm.  Hiệu quả: triệt tiêu toàn bộ tần số năng lượng nhắm về phía bản thân và đồng đội. Không tạo trạng thái “tàng hình” và không thể che giấu những hành động gây chấn động lớn. "', 'Mỗi lần hoàn thành một trận, Cầm sư phải chịu ù tai và mất thính lực tạm thời, nếu cưỡng ép duy trì trận quá thời gian cho phép, có nguy cơ chảy máu tai, mất thăng bằng hoặc tổn thương thính giác.', '', 0, 0, '2.0', 'Nhạy cảm với các giác quan', 4, 'Ù tai', 4, 'Chấp niệm ăn mòn', 4, '', 0, 'Cầm sư', 'Tố Kiều Lê', 'Trúc Khinh Nhu', 'Cầm sư', 'Đã duyệt'),
('Cầm trận - Dẫn Âm', '"Mỗi khi tấu đàn theo một âm luật nhất định, người sử dụng có thể thiết lập một trận pháp bằng các điểm cộng hưởng âm thanh trong phạm vi. Khi trận hoàn thành, khu vực bên trong sẽ bị ảnh hưởng bởi quy luật âm thanh được thiết lập.  Cách kích hoạt: Dùng cổ cầm tấu liên tiếp các âm theo đúng âm luật. Mỗi âm sẽ xác lập một trận điểm. Cần tối thiểu 3 trận điểm để hình thành trận, tối đa 5 trận điểm  Hiệu quả: tạo ra một nguồn âm thanh đặc biệt, có khả năng thu hút ma quỷ và tà vật xung quanh. Khi bị ảnh hưởng bởi Dẫn Âm, quỷ quái sẽ chịu ảnh hưởng phân tâm/thu hút, khiến chúng bị giữ chân quanh luồng âm thanh trong vòng 5 phút. "', '"Mỗi lần hoàn thành một trận, Cầm sư phải chịu ù tai và mất thính lực tạm thời, nếu cưỡng ép duy trì trận quá thời gian cho phép, có nguy cơ chảy máu tai, mất thăng bằng hoặc tổn thương thính giác. "', '', 0, 0, '2.0', 'Rối trí', 4, 'Đau đầu', 4, 'Bất tịnh', 4, '', 0, 'Cầm sư', 'Tố Kiều Lê', 'Trúc Khinh Nhu', 'Cầm sư', 'Đã duyệt'),
('Cầm trận - Hộ Âm', '"Mỗi khi tấu đàn theo một âm luật nhất định, người sử dụng có thể thiết lập một trận pháp bằng các điểm cộng hưởng âm thanh trong phạm vi. Khi trận hoàn thành, khu vực bên trong sẽ bị ảnh hưởng bởi quy luật âm thanh được thiết lập.  Cách kích hoạt: Dùng cổ cầm tấu liên tiếp các âm theo đúng âm luật. Mỗi âm sẽ xác lập một trận điểm. Cần tối thiểu 3 trận điểm để hình thành trận, tối đa 5 trận điểm.  Hiệu quả: duy trì một trận pháp sóng âm, bảo vệ người bên trong không bị ảnh hưởng linh trí. Đồng thời hồi phục tinh thần và khôi phục 30% trạng thái tỉnh táo cho người bên trong."', 'Mỗi lần hoàn thành một trận, Cầm sư phải chịu ù tai và mất thính lực tạm thời, nếu cưỡng ép duy trì trận quá thời gian cho phép, có nguy cơ chảy máu tai, mất thăng bằng hoặc tổn thương thính giác.', '', 0, 0, '3.0', 'Lãnh cảm', 4, 'Suy nhược', 2, 'Linh hồn chịu áp lực lớn', 2, '', 0, 'Cầm sư', 'Tố Kiều Lê', 'Trúc Khinh Nhu', 'Cầm sư', 'Đã duyệt'),
('Huyết Nhãn (cận chiến)', 'Mỗi khi cầu nguyện để kích hoạt năng lực, người sử dụng dùng máu của chính mình vẽ lên giữa trán một vòng tròn không khép kín. Sau khi khai nhãn, trong khoảng thời gian ngắn có thể nhìn thấy linh thể hoặc âm khí ở phạm vi gần. Khi đối mặt trực tiếp với một mục tiêu, Huyết Nhãn đôi lúc sẽ nhìn thấy một điểm có màu sắc hoặc khí tức khác thường trên người đối phương. Điểm này không cố định, không phải lúc nào cũng xuất hiện và không đồng nghĩa với điểm yếu. Nếu dùng binh khí đánh trúng, nhiều nhất chỉ có thể khiến linh thể bị ảnh hưởng rõ hơn so với một đòn đánh thông thường; hiệu quả cụ thể vẫn phụ thuộc vào bản thân mục tiêu. Huyết Nhãn không nhìn thấu được mọi thứ, không tìm ra tử huyệt, không nhìn xuyên vật cản và không tăng sức mạnh hay phản ứng của người sử dụng. Sau khi khai nhãn, mắt sẽ đau và nhìn mờ trong một thời gian; nếu tiếp tục sử dụng khi thị lực chưa hồi phục, khả năng nhìn thấy của lần sau sẽ giảm rõ rệt. Việc lạm dụng lâu dài có thể khiến người sử dụng thường xuyên nhìn thấy những bóng mờ không rõ thật giả.', 'Thị lực giảm thêm 0.5 đơn vị (tổng là 1.5 đơn vị), 10 ml máu nguyên bản, không ảnh hưởng tinh thần nếu không quá thời gian.', '', 0, 0, '2.0', 'Ảo giác', 3, 'Mất một phần thị lực', 5, 'Linh hồn chịu áp lực lớn', 5, '', 0, 'Âm dương sư', 'Khổng Mạch Chương', 'Thường Quý Thời', 'Âm dương sư', 'Chưa duyệt'),
('Hắc Tiễn (tầm xa)', 'Sau khi khai mở Huyết Nhãn, người sử dụng có thể dùng máu của mình làm dẫn, ngưng tụ thành một mũi tên mang theo khí tức âm hàn. Mỗi lần sử dụng chỉ có thể tạo ra một mũi tên. Hắc Tiễn không có khả năng xuyên qua vật cản và vẫn cần được bắn trúng mục tiêu như một mũi tên thông thường. Nếu đánh trúng linh thể yếu, mũi tên có thể khiến hình thể của đối phương dao động hoặc lưu lại một vết thương nhỏ; nếu mục tiêu quá mạnh, mũi tên có thể chỉ xuyên qua mà không để lại ảnh hưởng đáng kể. Hắc Tiễn không có hiệu ứng nguyền rủa, không đánh dấu mục tiêu từ xa, không tự truy đuổi và không gây sát thương liên tục. Sau khi bắn, mũi tên sẽ tan đi. Mỗi lần ngưng tụ đều cần dùng máu của bản thân, vì vậy không thể liên tục sử dụng nhiều lần mà không ảnh hưởng đến thể lực. Gây dame 50% với Du Hồn, 30% với Oán hồn, 10% với Lệ Qủy', 'bị kiệt sức trong 5 cmt, tiêu hao thêm 50 ml máu của bản thân (tổng 60 ml máu).', '', 0, 0, '2.0', 'Khỏe mạnh', 0, 'Mất máu, Kiệt sức', 5, 'Bất tịnh', 4, '', 0, 'Âm dương sư', 'Khổng Mạch Chương', 'Thường Quý Thời', 'Âm dương sư', 'Chưa duyệt'),
('Linh Trận (khống chế)', 'Sau khi khai mở Huyết Nhãn, người sử dụng dùng máu vẽ một dấu đơn giản lên lòng bàn tay, sau đó đặt tay lên mặt đất hoặc một vị trí cố định để hình thành một vùng Linh Trận nhỏ. Linh Trận chỉ có tác dụng trong phạm vi hẹp, đủ để bao phủ một vị trí hoặc một người đứng gần, và phải được chuẩn bị trước chứ không thể tùy ý lập tức xuất hiện dưới chân mục tiêu đang di chuyển. Khi linh thể đi vào phạm vi trận, âm khí xung quanh có thể trở nên nặng hơn, khiến mục tiêu có cảm giác bị cản trở trong chốc lát. Với linh thể yếu, tác dụng có thể khiến đối phương chậm lại một nhịp; với linh thể mạnh, nhiều khả năng chỉ gây ra sự khó chịu hoặc hoàn toàn không có tác dụng. Linh Trận không thể trói buộc hoàn toàn, không thể phong ấn năng lực, không gây sát thương và không thể duy trì lâu. Nếu người sử dụng rời quá xa hoặc trận bị phá hỏng, hiệu lực sẽ lập tức biến mất. Khống chế 60% với Du hồn, 40% với Oán hồn, 20% với Lệ Qủy', 'trong thời gian duy trì phải bất động (không tính trường hợp được cõng/bế...). Quá 2 cmt sẽ bị pháp trận phản phệ, sau khi trận tan sẽ bị giảm thêm 1 đơn vị thị lực, gặp ảo giác mức độ nặng, tiêu hao thêm 50 ml máu (chảy máu mũi) và tê liệt trong 1 cmt.', '', 0, 0, '2.0', 'Khỏe mạnh', 0, 'Mất một phần thị lực, "Hoa mắt, choáng váng", Mất máu', 5, 'Bất tịnh', 4, '', 0, 'Âm dương sư', 'Khổng Mạch Chương', 'Thường Quý Thời', 'Âm dương sư', 'Chưa duyệt'),
('Quy Lộ (càn quét)', 'Trong trạng thái Huyết Nhãn, người sử dụng có thể dùng máu đã có sẵn để vạch thành một đường máu trên mặt đất. Quy Lộ không điều khiển máu, không khiến máu tự di chuyển và không thể rút máu từ cơ thể bất kỳ ai. Sau khi được vạch ra, con đường máu chỉ lưu lại khí tức của người sử dụng trong một khoảng thời gian ngắn. Một số linh thể có thể nhận ra hoặc bị thu hút bởi khí tức này, vì vậy Quy Lộ được dùng để thử dò, dẫn dụ hoặc xác định xem khu vực đó có tồn tại dị vật hay không. Nếu linh thể không có phản ứng với khí tức máu, Quy Lộ sẽ không có tác dụng. Khi máu khô đi hoặc bị nước, đất và các yếu tố bên ngoài làm xóa mất, Quy Lộ cũng tự mất hiệu lực. Tất cả mục tiêu đứng trên đường máu này đều bị giảm 40% tốc độ di chuyển và chịu hiệu ứng ăn mòn, liên tục mất máu theo thời gian, mỗi 100 ml máu/giây, kéo dài 5 giây, giảm dần 50 ml các giây sau đó', 'Thị lực giảm thêm 0.5 đơn vị (tổng là 1.5 đơn vị), 10 ml máu nguyên bản, không ảnh hưởng tinh thần nếu không quá thời gian.', '', 0, 0, '3.0', 'Căng thẳng', 5, 'Mất một phần thị lực, Kiệt sức, Mất máu', 4, 'Bất tịnh', 4, '', 0, 'Âm dương sư', 'Khổng Mạch Chương', 'Thường Quý Thời', 'Âm dương sư', 'Chưa duyệt'),
('Tố Hình', 'Tận dụng đất, gỗ, bột khoáng, sáp, giấy, vải hoặc bất kỳ vật liệu nào có sẵn xung quanh, Dương Ngạn nhanh chóng tạo hình nhân vật, động vật, vũ khí hoặc vật thể với kích thước khác nhau để đánh lừa thị giác ở khoảng cách nhất định, dùng làm rào cản tạm thời trong giao tranh. Mỗi dị sự chỉ được Tố Hình 2 lần, chỉ mô phỏng được hình thái, không thể tái tạo hoàn toàn công năng của vật thật.  Trong môi trường khép kín không có vật liệu sẽ không thể sử dụng kỹ năng. Thời gian tạo vật sẽ mất từ 1-3 cmts tuỳ vào kích thước của vật thể', 'Không', '', 0, 0, '2.0', 'Căng thẳng', 3, 'Đau nhức', 3, 'Thanh khiết', 0, '', 0, 'Âm dương sư', 'Mộ Bách Thời', 'Dương Ngạn', 'Âm dương sư', 'Đã duyệt'),
('Định Cảnh', 'Ghi nhớ cảnh vật trước mắt bằng khả năng quan sát và hội họa của mình. Trong tâm trí hắn, toàn bộ cảnh tượng được tái dựng thành một bức họa không gian nhiều lớp, bao gồm phương vị, khoảng cách, độ cao thấp, vật cản, vị trí đã bị dịch chuyển.  Hắn có thể nhớ lại chính xác những gì đã nhìn thấy. Thông qua việc đối chiếu những gì mắt nhìn thấy với bức tranh được ghi nhớ, một khi phát hiện cảnh vật hiện tại khác với ký ức, hắn lập tức biết nơi đây đã xảy ra biến đổi.', 'Không', '', 10, 0, '2.0', 'Nhạy cảm với các giác quan, Căng thẳng, Không thể tập trung', 5, 'Mất một phần thị lực, Đau đầu, Suy nhược', 3, 'Bất tịnh', 3, '', 0, 'Âm dương sư', 'Mộ Bách Thời', 'Dương Ngạn', 'Âm dương sư', 'Đã duyệt'),
('Phá Họa', 'Toàn bộ khả năng cảm nhận hình ảnh được đẩy đến giới hạn và không bị bất kì tác động nào ảnh hưởng. Dương Ngạn có thể nhìn thấu những sai lệch cực nhỏ trong tranh họa, màu sắc, đường nét, bố cục và không gian, phát hiện tác phẩm giả tạo, dấu vết bị che giấu, trận đồ ẩn, điểm bất thường và những chi tiết không hòa hợp với tổng thể. Từ đó giúp phá giải trận địa, tìm cửa sinh trong cửa tử.', 'thể chất và tinh thần suy giảm nặng.', '', 100, 0, '', 'Ký ức hỗn loạn, Quá tải giác quan, Suy sụp', 5, 'Kiệt sức, Thị lực suy giảm mạnh', 5, 'Bất tịnh, Âm khí xâm nhập', 5, '', 0, 'Âm dương sư', 'Mộ Bách Thời', 'Dương Ngạn', 'Âm dương sư', 'Đã duyệt'),
('Ẩm Hồn Ti Trinh', 'Thả ra một vài con Âm Hồn Điệp hoặc cổ trùng trinh sát siêu nhỏ từ trong tay áo, dùng ý niệm và tiếng huýt sáo khẽ để điều khiển chúng hòa vào không gian xung quanh. Giúp dò tìm sự hiện diện của oán khí, chướng khí, tà vật hoặc bẫy rập ẩn giấu sau tường, trong bóng tối hoặc khu vực sương mù mà mắt thường không thể nhìn thấy. Kỹ năng này mang tính chất trinh sát thầm lặng, không trực tiếp gây sát thương vật lý lên tà vật hay kẻ địch', '', '', 20, 0, '2.0', 'Căng thẳng', 5, '"Hoa mắt, choáng váng", Đau đầu, Mất máu', 5, 'Thanh khiết', 0, '', 0, 'Sát thủ nuôi cổ', 'Lạng Tích Viễn', 'Lương Tú', 'Sát thủ nuôi cổ', 'Đã duyệt'),
('Bách Độc Phi Tiêu', 'Tung ra một loạt phi tiêu tẩm nọc độc từ cổ tay nhằm đánh úp chớp nhoáng ở cự ly ngắn. Khóa chặt đường di chuyển, áp sát và tiêu diệt nhanh chóng mục tiêu hoặc tà vật trước khi chúng kịp phản ứng. Nọc độc tác động trực tiếp vào hệ thần kinh và thể chất của mục tiêu đối với thực thể, gây tê liệt cơ bắp, ăn mòn huyết mạch ngay từ đòn tấn công đầu tiên.  Yêu cầu mua độc dược từ phía y quán mới có thể sử dụng, nếu không mua thì không thể dùng. Trong khu vực kín không có côn trùng thì không thể điều động', 'Không', '', 20, 0, '', 'Căng thẳng, Bất an', 5, 'Buồn nôn, Đau nhức, Khó thở, Mất máu', 5, 'Bất tịnh', 3, '', 0, 'Sát thủ nuôi cổ', 'Lạng Tích Viễn', 'Lương Tú', 'Sát thủ nuôi cổ', 'Đã duyệt'),
('Thiết Giáp Tụy Trùng Trận', 'Rạch đầu ngón tay lấy huyết dịch, vẽ một đạo huyết chú xuống mặt đất kết hợp với việc tung ra rết răng sắt kết hợp với cổ trùng điều khiển côn trùng, dựng một bức tường phòng thủ quanh thân. Rết răng sắt sẽ là chỉ huy, điều khiển bầy côn trùng dựng thành một màn lưới bảo vệ dày đặc. Chỉ cần có chỗ nào bị hở ra, Rết răng sắt sẽ đảm nhận nhiệm vụ vá lại hoặc nhe nanh ra để cắn không cho kẻ thù xâm nhập.  Khiến kẻ địch xông vào vòng trận bị lớp vỏ cứng cùng khí độc của bầy côn trùng độc cản trở, đồng thời ép chúng phải tiếp xúc với chướng khí và độc tính dày đặc do trận pháp khuếch đại, gây tổn hại nặng nề đến thể chất của chúng.', 'Đánh đổi bằng máu để vẽ chú. Chỉ dùng 1 dị sự 1 lần, khi kẻ địch tấn công sẽ tiêu hao côn trùng, trong khu vực kín không có côn trùng không thể sử dụng', '', 20, 0, '2.0', 'Căng thẳng', 5, 'Vết rách nhỏ trên da., Mất máu, Suy nhược', 5, 'Thanh khiết', 0, '', 0, 'Sát thủ nuôi cổ', 'Lạng Tích Viễn', 'Lương Tú', 'Sát thủ nuôi cổ', 'Đã duyệt'),
('Vạn Độc Phệ Tâm', 'Giải phóng hoàn toàn con Hắc Xà Cổ chủ lực, cho phép nó cắn sâu vào cổ tay mình để hút lấy lượng huyết dịch đậm đặc chứa đầy linh lực và độc tính cực hạn. Phóng thích một vùng cấm địa độc dược và sương mù tím đen bao trùm quanh thân, tạo thành đòn tấn công chí mạng. Ăn mòn thể chất trong phạm vi ảnh hưởng, khiến chúng không còn đường lui, chấn nhiếp đẩy lui du hồn và oán hồn trong thời gian ngắn', 'Tổn hại nghiêm trọng đến nguyên khí, mất đi một lượng lớn máu tươi và phải chịu phản phệ đau đớn từ chính con Hắc Xà chủ lực và bầy cổ trùng cắn ngược.', '', 20, 0, '3.0', 'Mơ hồ, Căng thẳng, Kiệt quệ', 5, 'Suy nhược, Xuất huyết nặng, Kiệt sức', 5, 'Bất tịnh', 5, '', 0, 'Sát thủ nuôi cổ', 'Lạng Tích Viễn', 'Lương Tú', 'Sát thủ nuôi cổ', 'Đã duyệt'),
('Lạc Bàn Định Sát', 'Dao Quang dùng La kinh bằng đồng thấu quang kết hợp với thước Lỗ Ban để đo đạc từ trường và phương vị phong thủy trong bán kính 10 mét. Thông qua sự rung động của kim chỉ nam và sự thay đổi nhiệt độ trên mặt La kinh, nàng có thể xác định chính xác mắt bẫy của âm khí, dự đoán hướng di chuyển hoặc nơi ẩn nấp của tà vật cấp thấp trong không gian kín. Kỹ năng này đóng vai trò trinh sát và thiết lập nền tảng để bố trí trận pháp. Yêu cầu người sử dụng phải đứng yên tại một vị trí, tập trung cao độ và không được phòng thủ trong thời gian đo đạc (khoảng 15-30 giây). Nếu bị tà vật tấn công ngắt quãng, La kinh có thể bị nhiễu loạn từ trường, dẫn đến phán đoán sai lệch phương vị.', '', '', 0, 0, '1.0', 'Căng thẳng', 2, '"Hoa mắt, choáng váng"', 2, 'Thanh khiết', 0, '', 0, 'Đạo sĩ', 'Dao Quang', 'Dao Quang', 'Đạo sĩ', 'Đã duyệt'),
('Cửu Cung Toả Linh Trận', 'Cách thi triển: Dao Quang dùng thước Lỗ Ban bằng đồng vạch định phương vị bát quái dưới đất, phóng ra 8 đồng tiền Ngũ Đế đã tẩm chu sa cắm vào 8 cung (Càn, Khảm, Cấn, Chấn, Tốn, Ly, Khôn, Đoài), nối các điểm bằng chỉ đỏ phong thủy rồi điểm trung cung để kích hoạt. Công dụng: Biến không gian trong bán kính trận pháp thành một lồng giam cô lập âm sát khí. Tác động đến đối tượng: Trói chân: Quỷ hồn khi bước vào bị tơ khí vô hình khóa chặt hạ bàn, không thể di chuyển hoặc dùng quỷ thuật ẩn thân/dịch chuyển. Suy yếu oán khí: Dương khí của chu sa và đồng tiền liên tục thiêu đốt tà khí, làm giảm 40% uy lực kỹ năng của quỷ và ngăn chặn quỷ hấp thụ tử khí xung quanh để hồi phục.', '"Không tiêu hao âm đức/công đức (do đây là pháp thuật Đạo môn thuần chính phục ma).  Nhưng tiêu hao đáng kể linh lực bản thân và cần thời gian tập trung duy trì; nếu trận bị ngoại lực phá vỡ đột ngột từ mắt trận, người thi triển sẽ bị phản phệ khí huyết."', '', 0, 0, '1.0', 'Nhạy cảm với các giác quan', 3, 'Suy nhược, Suy giảm nặng các giác quan, Xuất huyết nặng', 3, 'Linh hồn chịu áp lực lớn, suy giảm khả năng phân biệt âm dương', 3, '', 0, 'Đạo sĩ', 'Dao Quang', 'Dao Quang', 'Đạo sĩ', 'Đã duyệt'),
('Tứ Tượng Huyền Quy', 'Cách thi triển: Dao Quang cắm 4 thẻ gỗ đào phong ấn linh phù tại 4 góc Đông - Tây - Nam - Bắc (Thanh Long, Bạch Hổ, Chu Tước, Huyền Vũ), dùng đầu thước Lỗ Ban gõ nhẹ 3 nhịp xuống mặt đất để dựng kết giới. Công dụng: Tạo ra một màng chắn quang minh hình mai rùa bao bọc đồng đội bên trong, ngăn cách hoàn toàn các tác động tâm linh và ô uế từ Quỷ Vực. Tác động đến đối tượng: Đồng đội bên trong: Được miễn nhiễm với các trạng thái mê hoặc, ảo giác âm thanh (tiếng kèn hỷ, tiếng than khóc), và chặn đòn tấn công vật lý/oán sát tầm xa của quỷ. Quỷ dị chạm vào: Khi quỷ hồn cố lao qua màng chắn sẽ bị cương khí huyền môn đẩy lùi và thiêu đốt linh thể.', '', '', 0, 0, '1.0', 'Quá tải giác quan, Căng thẳng', 5, 'Suy nhược, Khó thở, Tê liệt', 5, 'suy giảm khả năng phân biệt âm dương, Âm khí xâm nhập', 4, '', 0, 'Đạo sĩ', 'Dao Quang', 'Dao Quang', 'Đạo sĩ', 'Đã duyệt'),
('Thiên Cương Bắc Đẩu Trận', 'Cách thi triển: Dao Quang dùng thước Lỗ Ban dẫn đạo linh lực, phóng ra 7 mũi Đinh Táng Hồn (hoặc 7 kiếm gỗ đào khảm tiền cổ) cắm xuống mặt đất theo đúng hình thế chòm sao Bắc Đẩu (Tham Lang, Cự Môn, Lộc Tồn, Văn Khúc, Liêm Trinh, Vũ Khúc, Phá Quân), kết hợp niệm chú điểm chỉ vào vị trí Phá Quân để kích hoạt lôi hỏa. Công dụng: Biến phương vị trận thành sát trận lôi phạt của Đạo gia, giáng thẳng cương khí trừ tà xuống mục tiêu bị định vị. Tác động đến đối tượng: Sát thương trực diện: 7 cột cương khí ánh kim giáng xuống cùng lúc, đánh thẳng vào linh thể và tử huyệt của quỷ dị, thiêu đốt các hỷ vật/khí cụ oán hận. Phá quỷ vực: Đánh tan kết cấu không gian méo mó xung quanh mục tiêu, cưỡng chế giải trừ trạng thái cuồng nộ và áp chế lượng lớn sát khí của quỷ.', '', '', 0, 0, '1.0', 'Rối loạn nhận thức, Tinh thần tan rã', 7, 'Tê liệt, Mất thính giác', 7, 'Tà khí nhập thể, Âm khí xâm nhập, Oán khí quấn thân', 5, '', 0, 'Đạo sĩ', 'Dao Quang', 'Dao Quang', 'Đạo sĩ', 'Đã duyệt'),
('Mật Khóa Giải Cơ', 'Có khả năng quan sát và ghi nhớ cấu tạo của các loại cơ quan, mật khóa và chốt ngầm. Khi phát động, có thể lần theo dấu vết nhỏ nhất để tìm ra điểm then chốt, từ đó vô hiệu hóa hoặc mở khóa cơ quan trong thời gian ngắn. Nếu cơ quan quá phức tạp, có thể xác định được cách vận hành và điểm nguy hiểm để tránh kích hoạt nhầm, có tỷ lệ sai sót 30%', 'Không được dùng 2 Dị sự liên tiếp.', '', 20, 0, '2.0', 'Nhạy cảm với các giác quan', 5, 'Khỏe mạnh', 0, 'Thanh khiết', 0, '', 0, 'Trộm mộ', 'Kiêu Hoàng Sương', 'Tiểu Tiên Nữ', 'Trộm mộ', 'Đã duyệt'),
('Vọng Huyệt Biện Long', 'Dựa vào địa thế, hướng núi, mạch nước, thổ nhưỡng và dấu tích nhân tạo để phán đoán vị trí huyệt mộ. Khi phát động, có thể nhanh chóng nhận biết nơi nào từng bị đào bới, xác định phương hướng của huyệt đạo và tìm ra điểm có khả năng tồn tại mật thất hoặc đường ngầm. Kỹ năng đặc biệt hữu dụng khi tiến vào những khu vực địa hình phức tạp, giúp tránh đi nhầm đường hoặc chạm phải cơ quan mai phục. Có tỷ lệ sai sót 40%', '', '', 20, 0, '3.0', 'Nhạy cảm với các giác quan, Căng thẳng', 5, 'Đau nhức, Đau đầu', 5, 'Thanh khiết', 0, '', 0, 'Trộm mộ', 'Kiêu Hoàng Sương', 'Tiểu Tiên Nữ', 'Trộm mộ', 'Đã duyệt'),
('Cổ Văn Giải Mật', 'am hiểu các loại văn tự cổ, mật tự, ký hiệu và văn thư thường được lưu lại trong mộ thất. Khi phát động, có thể nhận biết niên đại, loại chữ và ý nghĩa sơ bộ của văn bản, đồng thời đối chiếu những ký hiệu đặc biệt để giải mã nội dung ẩn giấu, từ đó tìm ra manh mối về chủ nhân, cơ quan hoặc bố cục của huyệt mộ. Chỉ áp dụng khi ở trong huyệt mộ, có tỷ lệ nhầm lẫn 30%', '', '', 20, 0, '2.0', 'Khỏe mạnh', 0, 'Đau đầu, "Hoa mắt, choáng váng"', 5, 'Thanh khiết', 0, '', 0, 'Trộm mộ', 'Kiêu Hoàng Sương', 'Tiểu Tiên Nữ', 'Trộm mộ', 'Đã duyệt'),
('Đồng Sinh', '"Kỷ Huy dùng đồng xu làm vật dẫn, đặt lên cơ thể mục tiêu rồi vận khí theo huyệt đạo để thúc đẩy sinh lực. Đồng xu hấp thu phần khí huyết hỗn loạn quanh vết thương, sau đó chuyển hóa thành sinh khí để chữa trị.  Kỹ năng có tác dụng hồi phục sinh lực, cầm máu và chữa trị thương thế, hiệu quả cao nhất đối với các tổn thương vật lý. Với những thương thế nghiêm trọng, Đồng Sinh có thể kéo mục tiêu khỏi trạng thái nguy hiểm nhưng không thể khiến vết thương biến mất hoàn toàn trong một lần sử dụng.  Kỷ Huy có thể dùng kỹ năng lên bản thân nhưng hiệu quả chỉ bằng khoảng 79% so với khi chữa trị cho người khác.  Khi đồng xu rơi xuống, mặt Dương ngửa thì lượng sinh khí được dẫn ra tăng lên, mặt Âm ngửa thì ưu tiên ổn định thương thế và cầm máu."', '', '', 0, 0, '3.0', '', 0, '', 0, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('Định Sinh', '"Kỷ Huy ném một đồng xu lên không trung, dùng linh lực cố định đồng xu tại vị trí nhất định để định trạng thái sinh mệnh của mục tiêu.  Trong thời gian hiệu lực, mục tiêu được bảo hộ bởi một lớp lực vô hình. Các đòn đánh vẫn có thể tác động lên cơ thể nhưng sát thương nhận vào bị giảm đáng kể, đồng thời những thương thế vốn có sẽ không tiếp tục chuyển biến xấu. Người đang chảy máu sẽ không tiếp tục mất máu, người bị thương nặng sẽ không lập tức rơi vào trạng thái nguy hiểm hơn, đồng thời khả năng bị hất văng, gián đoạn hành động hoặc chịu một số hiệu ứng khống chế cũng được giảm bớt.  Định Sinh không hồi máu. Nó chỉ giữ mục tiêu ở trạng thái an toàn trong một khoảng thời gian, tạo cơ hội để Kỷ Huy hay đồng đội tiến hành chữa trị ngay sau đó.  Hắn có thể dùng Định Sinh lên bản thân. Nếu tập trung toàn bộ pháp lực vào một mục tiêu, hiệu quả bảo hộ sẽ đạt mức cao nhất."', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('Phán Âm', '"Kỷ Huy dùng đồng xu để quan sát sự vận hành của khí huyết, linh lực và âm khí trong cơ thể đối phương. Sau một khoảng thời gian quan sát, hắn có thể xác định điểm yếu hoặc nơi khí mạch mất cân bằng của mục tiêu.  Kỷ Huy búng đồng xu vào vị trí đã xác định. Đồng xu không đơn thuần gây sát thương mà đánh thẳng vào điểm yếu, gây đau, làm gián đoạn vận khí và khiến mục tiêu mất khả năng phát huy một phần năng lực trong thời gian ngắn.  Đối với tà vật, oán linh hoặc sinh vật mang âm khí, hiệu quả mạnh hơn. Đồng xu có thể ghim phần âm khí đang lưu chuyển, khiến mục tiêu bị trì trệ hoặc tạm thời mất một năng lực đang vận hành.  Nếu hắn liên tục quan sát cùng một mục tiêu, độ chính xác của Phán Âm tăng dần. Vì vậy, đây là kỹ năng giúp hắn càng kéo dài giao chiến càng có lợi."', '', '', 0, 0, '', 'Ảo giác', 1, '', 0, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('Hoán Mệnh', '"Tung một đồng xu lên cao, dùng linh lực liên kết bản thân với đồng đội và mục tiêu đã được hắn đánh dấu.  Khi đồng xu rơi xuống, hắn có thể hoán chuyển một phần trạng thái thương tổn giữa các mục tiêu.  Nếu dùng lên đồng đội, Kỷ Huy có thể kéo một phần thương thế nghiêm trọng của họ về phía mình, đồng thời chuyển hóa lượng thương tổn đó thành sinh lực để hồi phục cho mục tiêu. Kỷ Huy càng nhận nhiều thương thế, hiệu quả hồi phục cho đồng đội càng lớn.  Nếu dùng lên kẻ địch, hắn có thể chuyển hóa một phần thương thế mà đối phương đã gây ra cho đồng đội thành phản thương, đánh ngược lại chính kẻ gây ra nó.  Đồng xu quyết định hướng vận chuyển sau khi rơi xuống:  Mặt Dương: ưu tiên cứu chữa và chuyển thương về hắn. Mặt Âm: ưu tiên phản thương lên đối phương.  Kỷ Huy không thể kiểm soát kết quả của đồng xu sau khi đã tung. Không thể dùng Hoán Mệnh để hồi sinh người đã chết hoặc chuyển toàn bộ thương tổn của một người sang người khác."', 'Kỷ Huy phải chịu phản phệ tương ứng với lượng thương thế được hoán chuyển. Nếu cứu một người đang ở trạng thái cực kỳ nguy hiểm, bản thân hắn có thể bị thương nặng hoặc mất khả năng tiếp tục chiến đấu trong thời gian ngắn.', '', 0, 0, '', '', 0, 'Ù tai, Khó thở, Đau đầu', 3, '', 0, '', 0, 'Y sư', 'Tôn Đạo Sinh', 'Chương Kỷ Huy', 'Y sư', 'Chưa duyệt'),
('NGỌC PHIẾN ĐOẠT HỒN', '"Phiến ngọc có cơ chế giấu châm tẩm độc dược trong cán quạt. Khi không kích hoạt cơ chế bắn ra châm độc thì được sử dụng như quạt cầm tay thông thường. Sát thủ sử dụng các ám khí đã được chuẩn bị từ trước, kết hợp với độc gây suy yếu để kiểm soát khoảng cách và tạo sơ hở từ đó tập trung toàn bộ sức lực vào một đòn đánh chính xác vào điểm yếu của đổi thủ. Hiệu quả Gây tê liệt, chóng mặt, mất thị giác hoặc suy giảm khả năng vận động tùy loại độc trong bối cảnh phó bản dị sự Có thể sử dụng để ngăn đối phương truy đuổi. Có khả năng kết thúc cuộc đối đầu nếu muc tiêu đã mất khả năng phòng thủ."', '', '', 10, 0, '', 'Khỏe mạnh', 0, 'Đau đầu, Ù tai, "Hoa mắt, choáng váng"', 4, 'Thanh khiết', 0, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Tỏa Khí', 'Dùng phù lục và pháp quyết để tạm thời che giấu khí tức của bản thân và 1 người ở gần, làm giảm khả năng bị các sinh vật hoặc dị sự cảm nhận thông qua khí tức. Duy trì trong 3 cmts với Du hồn, 2 cmts với Oán hồn và 1 cmt với Lệ quỷ', 'mỗi dị sự chỉ được dùng 1 lần', '', 20, 0, '46082.0', 'Căng thẳng', 5, 'Ù tai, "Hoa mắt, choáng váng"', 4, 'Bất tịnh', 5, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Cửu Cung Định Thế', 'Dựa trên Cửu Cung và phương vị để phân chia, ghi nhớ và phân tích bố cục của một khu vực. Thông qua vị trí cửa, đường đi, vật cản và các điểm giao nhau, người sử dụng có thể xác định hướng di chuyển phù hợp hoặc vị trí thuận lợi để bố trí nhân lực và vật dụng.', '', '', 20, 0, '', 'Căng thẳng', 5, '"Hoa mắt, choáng váng", Đau đầu, Suy nhược', 5, 'Thanh khiết', 0, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Thất Tinh Liên Sát', 'Bố trí bảy trận điểm theo thế Thất Tinh, mỗi điểm đảm nhiệm một vị trí trong chuỗi công kích. Người sử dụng lần lượt kích hoạt các điểm trận để tạo thành một thế công kích liên hoàn, hạn chế khả năng hành động của mục tiêu. Khi tạo trận tối thiếu phải dùng 3 lượt cmt để bày trận, trong quá trình bày trận nếu bị ngắt quãng sẽ bị phản phệ và bày trận lại từ đầu Gây sát thương 60% lên Du hồn, 40% lên Oán hồn và 20% lên Lệ quỷ, 10% lên Hung Sát, từ Hung Sát trở lên không có tác dụng', 'Chịu phản phệ mất máu, chịu tag đỏ thể chất trong 7 cmts', '', 30, 0, '2.0', 'Nóng nảy, Căng thẳng, Không thể tập trung', 5, 'Suy nhược, Đau nhức, "Hoa mắt, choáng váng", Xuất huyết nặng', 7, 'Bất tịnh', 5, '', 0, 'Sát thủ', 'Lâm Hàn Nghiễm', 'Củng Triệt', 'Sát thủ', 'Đã duyệt'),
('Tiền Đồng Ngũ Đế', 'Dùng năm đồng ngũ đế theo ngũ hành để ổn định trường khí trong một phạm vi 5m, cần thiết có thể giảm ảnh hưởng của oán khí so với phạm vi, đồng thời làm suy yếu một luồng tà khí nếu thay đổi cách bày trận.', '', '', 0, 0, '2.0', 'Căng thẳng', 5, 'Đau đầu', 5, 'Thanh khiết', 0, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt'),
('Tụ Linh Trận', 'Bày một trận nhãn, sau đó bố trí 5 điểm dẫn khí xung quanh, tạo thành một vùng có năng lượng cao bình thường, tăng khả năng phục hồi năng lượng cho người ở trong trận, có thể cường hóa kỹ năng của đối phương lên thêm một bậc. Bày trận trong tối thiểu 3 cmts, nếu trong quá trình bày trận bị cắt ngang buộc phải bày lại từ đầu.', '', '', 20, 0, '2.0', 'Căng thẳng', 5, 'Đau đầu', 4, 'Thanh khiết', 0, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt'),
('Sơn Hà Chuyển Thế', 'Dùng la bàn truy tung và tiền đồng ngũ đế tạo thành một vùng  trấn áp trong 5m Năm đồng ngũ đế tượng trưng cho ngũ hành, dựng ở năm điểm khác nhau có thể khóa vị trí của quỷ trong phạm vi của trận. La bàn truy tung dùng để trấn huyệt, phong tỏa cố định điểm mà nó đang đứng. Hạn chế Du hồn trong 3 cmts, oán hồn 2 cmts, lệ quỷ 1 cmts', 'Tiêu hao từ 20% đến 70% thể lực để duy trì trận pháp, tuỳ theo cấp độ quỷ dị và độ khó của dị sự.  Không thể sử dụng trong 2 dị sự liên tiếp nhau', '', 46082, 0, '1 - 3', 'Mất phương hướng', 3, 'Suy nhược', 3, 'Âm khí xâm nhập', 3, '', 0, 'Địa sư', 'Khương Quỳ', 'Tưởng Ly', 'Địa sư', 'Đã duyệt'),
('Lưu Quang Toái Ảnh - Thừa Ảnh Kiếm Pháp', '"Thừa Ảnh kiếm sẽ liên tục chuyển động, mỗi lần xuất kiếm đều để lại một đạo linh lực cực mảnh, những đạo kiếm khí không nhất thiết mạnh, nhưng số lượng rất lớn và liên tục. Chiêu này thiên về Cắt, Phá và Bào Mòn.  Tác pháp: Người cầm kiếm vận linh lực vào cổ tay, liên tiếp xuất kiếm theo những quỹ đạo khác nhau, vì kiếm quá mảnh và tốc độ quá nhanh, kiếm ảnh chồng chất như từng mảnh lưu quang. Công dụng: Phong tỏa đường lui, ép tà vật hoặc đối thủ vào thế không thể tránh né. Tác động: Từng đạo kiếm ảnh phân tán giữa không trung, hư thực khó phân, tựa ánh trăng vỡ vụn trên mặt nước, trực tiếp áp tới khiến đối phương khó lòng tránh né.  Gây sát thương 50% với Du hồn, 30% với oán hồn, 10% với lệ quỷ, còn lại không có tác dụng. 1 Dị sự chỉ được dùng 1 lần', '', '', 20, 0, '2.0', 'Căng thẳng, Thất thần', 5, 'Đau nhức, Tê buốt kinh mạch', 7, 'Linh hồn chịu áp lực lớn', 5, '', 0, 'Pháp sư', 'Lễ Vinh Nhu', 'Thanh Trúc Kinh Giang', 'Pháp sư', 'Đã duyệt'),
('Dẫn Lôi - Thừa Ảnh Kiếm Pháp', '"Tác pháp: một tay kết Lôi Ấn, một tay dựng Thừa Ảnh kiếm trước thân. Lấy kiếm làm dẫn lôi chi vật, dùng phù văn hoặc linh lực khắc thành Lôi Văn trên thân kiếm. Niệm động khẩu quyết: "Cửu tiêu lôi động, thiên uy giáng thế. Dĩ kiếm vi dẫn, dĩ linh vi môi. Lôi nhập kiếm thân, tru tà phá u.  Sắc lệnh! " Công dụng: Bản chất của chiêu thức là dùng Thừa Ảnh kiếm làm vật dẫn, đưa lôi lực vào thân kiếm, vì kiếm cực mảnh, lôi lực không bùng nổ thành một khối lớn mà bị ép thành một đường điện quang cực nhỏ, cực cô đọng. Điểm đáng sợ nhất của chiêu này là không chỉ chém quỷ thể, mà lôi lực còn xâm nhập vào âm khí bên trong. Tác động: Lôi quang không tụ thành những tia điện thô bạo, mà men theo thân kiếm mảnh như từng sợi tơ bạc, mỗi lần Thừa Ảnh kiếm chém ra, một đường lôi tuyến mảnh lập tức xé rách âm khí. Gây sát thương 60% với Du hồn, 40% với oán hồn, 20% với lệ quỷ, còn lại không có tác dụng. 1 Dị sự chỉ được dùng 1 lần', '', '', 30, 0, '2.0', 'Quá tải giác quan', 5, 'Suy nhược', 5, 'Âm khí xâm nhập', 5, '', 0, 'Pháp sư', 'Lễ Vinh Nhu', 'Thanh Trúc Kinh Giang', 'Pháp sư', 'Đã duyệt'),
('Nhất Kiếm Phá Vọng - Thừa Ảnh Kiếm Pháp', 'Tác pháp: Thu toàn bộ kiếm ảnh, linh lực và lôi lực vào duy nhất một mũi kiếm, đây là chiêu một kiếm định thắng bại. Công dụng: dồn toàn lực một kích tất sát.  Tác động: Không có kiếm quang rực rỡ, chỉ có một đường sáng cực mảnh, gần như vô hình, xuyên thẳng qua hư không. Sau một thoáng tĩnh lặng lôi minh mới vang lên, âm khí sẽ bị đường kiếm chém đôi, kết giới hoặc huyễn cảnh cũng bị rạn nứt. Không thể phá âm khí của Quỷ Vương và Quỷ Tướng, phá âm khí nhưng không đồng nghĩa là lập tức khiến tà vật tử vong, tà vật vẫn có khả năng né tránh. Kết giới hoặc huyễn cảnh thông qua đường chém chỉ có thể rạn nứt, không thể triệt tiêu hoàn toàn.', '2 dị sự dùng 1 lần', '', 30, 0, '1.0', 'Quá tải giác quan', 5, 'Kiệt sức', 5, 'Âm khí xâm nhập', 5, '', 0, 'Pháp sư', 'Lễ Vinh Nhu', 'Thanh Trúc Kinh Giang', 'Pháp sư', 'Đã duyệt'),
('Ảnh Hành Vô Tích - Thừa Ảnh Kiếm Pháp', '"Đây là chiêu thiên về ẩn sát và xuyên phá,Thừa Ảnh kiếm vốn cực mảnh, khi linh lực phủ lên thân kiếm, nó gần như hòa vào hư không. Tác pháp: Linh lực rót dọc theo sống kiếm, thân kiếm mảnh đến mức gần như hòa lẫn vào hư không, chỉ lưu lại một đạo hàn quang thoáng qua. Công dụng: Đánh lạc cảm quan, khiến đối phương khó phân biệt chân kiếm và tàn ảnh. Tác động: Kiếm xuất vô thanh, chỉ đến khi một đường hàn mang lướt qua, sát ý mới chợt hiện, có thể tức khắc đâm vào chỗ yếu hại.  Gây sát thương 50% với Du hồn, 30% với oán hồn, 10% với lệ quỷ, còn lại không có tác dụng. 1 Dị sự chỉ được dùng 1 lần', '', '', 0, 0, '1.0', 'Căng thẳng, Thất thần', 5, 'Đau nhức, Tê buốt kinh mạch', 7, 'Linh hồn chịu áp lực lớn', 5, '', 0, 'Pháp sư', 'Lễ Vinh Nhu', 'Thanh Trúc Kinh Giang', 'Pháp sư', 'Đã duyệt'),
('Trừ tà', 'Vận linh lực vào đạo phù, dùng chỉ quyết và chú ngữ để kích hoạt. Sau khi đạo phù được dán lên người, vật bị quỷ ám hoặc mặt đất quanh mục tiêu, phù sẽ tạo ra một vùng trấn tà có bán kính khoảng 3m. Khi kích hoạt, linh lực dương khí từ đạo phù ép xuống, gây áp chế trực tiếp lên âm khí, gây tổn thương trực tiếp lên quỷ và làm gián đoạn năng lực của chúng. Đối với quỷ cấp thấp, hiệu quả có thể khiến chúng giảm tốc độ, gián đoạn việc thi triển năng lực hoặc bị ép hiện nguyên hình. Nếu mục tiêu đang nhập vào người sống, đạo phù có thể cưỡng chế quỷ tách khỏi vật chủ trong thời gian ngắn.', '', '', 0, 0, '4.0', '', 0, '', 0, '', 0, '', 0, 'Đạo sĩ', 'Đề Chủy Tửu', 'Kỷ Huyền Sâm', 'Đạo sĩ', 'Chưa duyệt'),
('Phong ấn', '"Thi triển Phong Ấn Tam Tài.   Trận pháp cần ba người đồng thời đảm nhiệm Thiên, Địa và Nhân Vị. KHS giữ Nhân Vị, dùng dùng khí lực và đạo hạnh của bản thân để kết nối, điều hòa và duy trì toàn bộ phong ấn, và hình thành màng chắn hình chóp tam giác cô lập mục tiêu.  Trận trải qua ba giai đoạn kết trận – duy trì – ép trận, gây áp chế âm khí, hạn chế di chuyển, tà thuật, xuất hồn và chuyển vị; quỷ cấp thấp có thể bị phong ấn hoàn toàn. Với quỷ cấp cao, trận chủ yếu có tác dụng giam giữ và bào mòn, không lập tức khiến mục tiêu mất khả năng phản kháng. Ba trận vị có thể chia sẻ một phần áp lực thông qua dòng linh lực, nhưng nếu một vị trí bị phá sẽ xảy ra hiệu ứng, khiến hai vị trí còn lại chịu phản chấn. Ba người phải duy trì sự đồng bộ tuyệt đối khi khai triển phong ấn. KHS không thể rời Nhân Vị hoặc chiến đấu bình thường trong lúc duy trì trận.  * Nếu một người đứng sai vị trí hoặc bị buộc phải di chuyển, trận sẽ mất cân bằng. Khi bị tấn công một trận vị, áp lực sẽ tác động lên cấu trúc trận và được phân tán một phần thông qua ba điểm. Vì vậy, người ở vị trí bị tấn công không nhất thiết phải chịu toàn bộ áp lực ngay lập tức. "', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Đạo sĩ', 'Đề Chủy Tửu', 'Kỷ Huyền Sâm', 'Đạo sĩ', 'Chưa duyệt'),
('Pháp Kiếm', 'Dùng chu sa bôi lên thân kiếm, biến kiếm thành vật dẫn có khả năng tác động trực tiếp lên âm thể của quỷ. Khi tiếp xúc với âm thể, chu sa sẽ phá vỡ và làm tiêu tán phần âm khí tại nơi bị chém khiến một phần âm thể tan rã. Có thể chém vào nơi âm khí ngưng tụ để làm suy yếu khả năng duy trì hình dạng và tà thuật của mục tiêu. Hữu dụng trong việc phá liên kết giữa quỷ và vật chủ.', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Đạo sĩ', 'Đề Chủy Tửu', 'Kỷ Huyền Sâm', 'Đạo sĩ', 'Chưa duyệt'),
('Trận pháp', 'Dùng kiếm găm xuống trung tâm trận làm trận nhãn, lấy chu sa vẽ thành hình Bát Quái quanh thân kiếm. Người thi triển vận khí, theo phương vị Cửu Cung lần lượt đặt chân vào các trận vị, khởi từ Khảm vị phương Bắc, lần lượt qua Khôn, Chấn, Tốn, quy Trung Cung, rồi chuyển Càn, Đoài, Cấn, Ly, cuối cùng hồi về Trung Cung, dẫn linh lực từ ngoài vào trong, khiến thế trận dần khép kín. Khi tám quẻ hoàn thành, kiếm tại tâm trận trở thành điểm khóa, Bát Quái đồng thời phát động, hình thành kết giới phong ấn, áp chế tà vật trong phạm vi trận pháp và ngăn chúng phá trận hoặc thoát ra ngoài.', '', '', 0, 0, '4.0', '', 0, '', 0, '', 0, '', 0, 'Thủ đền', 'Hạm Khanh Ngân', 'Trầm Sương', 'Thủ đền', 'Chưa duyệt'),
('Thanh tẩy, siêu độ', 'Mượn hạo nhiên chính khí của đền, niệm thần chú duy trì để thanh tẩy âm khí và oán niệm trên đối tượng. Khi thi triển, chính khí được truyền trực tiếp vào mục tiêu, áp chế tà khí, xua tan các trạng thái tiêu cực và làm suy yếu linh thể. Với những linh thể còn chấp niệm, chính khí sẽ dần hóa giải chấp niệm, đưa chúng trở về trạng thái thanh minh và hoàn thành siêu độ. Đối tượng càng nhiều oán niệm hoặc tà khí thì quá trình thanh tẩy càng khó khăn.', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Thủ đền', 'Hạm Khanh Ngân', 'Trầm Sương', 'Thủ đền', 'Chưa duyệt'),
('Phục hồi, trị thương', 'Truyền HP, công năng, linh lực,... giúp đồng đội phục hồi một phần lớn hao tổn do thi triển kỹ năng', '', '', 0, 0, '', '', 0, '', 0, '', 0, '', 0, 'Thủ đền', 'Hạm Khanh Ngân', 'Trầm Sương', 'Thủ đền', 'Chưa duyệt');